static unsigned long get_plt_size ( const Elf32_Ehdr * hdr , const Elf32_Shdr * sechdrs , const char * secstrings , int is_init ) { cfs_time_t ret = 0 ; unsigned i ; for ( i = 1 ; i < hdr -> e_shnum ; i ++ ) { if ( ( strstr ( secstrings + sechdrs [ i ] . sh_name , ".init" ) != NULL ) != is_init ) { continue ; } if ( strstr ( secstrings + sechdrs [ i ] . sh_name , ".debug" ) != NULL ) { continue ; } if ( sechdrs [ i ] . sh_type == SHT_RELA ) { pr_debug ( "Found relocations in section %u\n" , i ) ; pr_debug ( "Ptr: %p.  Number: %u\n" , ( void * ) hdr + sechdrs [ i ] . sh_offset , sechdrs [ i ] . sh_size / sizeof ( Elf32_Rela ) ) ; sort ( ( void * ) hdr + sechdrs [ i ] . sh_offset , sechdrs [ i ] . sh_size / sizeof ( Elf32_Rela ) , sizeof ( Elf32_Rela ) , relacmp , relaswap ) ; ret += count_relocs ( ( void * ) hdr + sechdrs [ i ] . sh_offset , sechdrs [ i ] . sh_size / sizeof ( Elf32_Rela ) ) * sizeof ( metag_plt_entry ) ; } } return ret ; } 